const res = $input.first().json.response;

function normalizarTelefono(cityCode, phoneNumber) {
  // Limpiar cityCode: sacar no-dígitos y ceros iniciales
  const area = (cityCode || '').replace(/\D/g, '').replace(/^0+/, '');
  const numero = (phoneNumber || '').replace(/\D/g, '');
  const completo = area + numero;

  if (!completo) return null;
  if (completo.startsWith('549')) return completo;
  if (completo.startsWith('54'))  return `549${completo.slice(2)}`;
  return `549${completo}`;
}

const telefonoNormalizado = normalizarTelefono(
  res.mobilePhone.cityCode,
  res.mobilePhone.phoneNumber
);

return [{
  json: {
    cliente_id:           res.id,
    nombre:               res.firstName,
    apellido:             res.lastName,
    nombre_completo:      `${res.firstName} ${res.lastName}`,
    dni:                  res.nationalId,
    email:                res.email,
    telefono_normalizado: telefonoNormalizado,
    //telefono_normalizado: "5491150997009"
  }
}];

